def check(ctx):
    pose = ctx.object_pose("u_green")
    if pose is None:
        return None
    if "initial" not in ctx.state:
        ctx.state["initial"] = pose["pose"]["position"]
        return None
    d = ctx.dist(ctx.state["initial"], pose["pose"]["position"])
    thr = ctx.value("disturbance_tolerance_m")
    if d > thr:
        return {"value": d, "detail": "u_green moved " + str(d) + "m from its initial position"}
    return None

